function openDiplomacy(){let list=[...allies].map(id=>nations.find(n=>n.id===id)?.name).filter(Boolean);let body=`<p>Build trust, trade, and secure mutual support. Alliances improve influence and can lower tension.</p><div class="detail"><small>CURRENT ALLIES</small><strong>${list.length?list.join(', '):'No formal alliances yet'}</strong></div><div style="margin-top:12px" class="detail"><small>SELECTED COUNTRY</small><strong>${selected.flag} ${selected.name} · Relations ${selected.relation}/100</strong></div><p>Choose a country on the map, then offer a pact from its nation panel.</p>`;modal('Diplomatic relations',body,'Review selected',()=>{closeModal();selectNation(selected);toast('Use the handshake option to propose an alliance.')})}
function update(){ $('#money').innerHTML=fmt(cash)+`<small>TREASURY</small>`;$('#turn').textContent=`TURN ${String(turn).padStart(2,'0')} · ${['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][(turn-1)%12]}`;$('#force-count').textContent=Object.values(units).reduce((a,b)=>a+b,0).toString().padStart(2,'0');$('#ally-count').textContent=String(allies.size).padStart(2,'0');$('#conflicts').textContent=String(wars.size+2).padStart(2,'0');$('#stability').textContent=stability+'%';$('#influence').textContent=(18.4+allies.size*1.2).toFixed(1)+'%';$('#readiness').textContent=`${Object.values(units).reduce((a,b)=>a+b,0)} divisions · balanced doctrine · readiness ${Math.max(28,86-fatigue)}%`;selectNation(selected)}
function endTurn(){turn++;cash+=12.4;let weakened=[];wars.forEach(id=>{let n=nations.find(x=>x.id===id);if(!n)return;fatigue++;n.power=Math.max(8,n.power-(turn%2===0?2:1));n.relation=Math.max(0,n.relation-2);if(turn%5===0){wars.delete(id);stability=Math.min(88,stability+2);log(`Armistice reached with ${n.name}; both sides exhausted.`);toast(`A ceasefire ends the conflict with ${n.name}.`)}else weakened.push(n.name)});if(wars.size===0)fatigue=Math.max(0,fatigue-5);else stability=Math.max(18,stability-1);$('#briefing').textContent=weakened.length?`Prolonged conflict is draining national readiness. ${weakened.join(', ')} is losing strength; consider a ceasefire.`:'Diplomatic channels are open. Your treasury is ready—choose your next move.';update();log(`Treasury grows by $12.4B. Turn ${turn} begins.`);toast('Turn advanced · +$12.4B income')}
function pact(){if(selected.own){toast('Choose another nation first.');return}if(allies.has(selected.id)){toast('You already have an alliance with this nation.');return}if(wars.has(selected.id)){toast('A ceasefire is needed before an alliance can be proposed.');return}if(selected.relation<25){toast('Relations are too tense. Improve relations with a trade deal first.');return}selected.relation=Math.min(100,selected.relation+12);allies.add(selected.id);log(`Alliance pact signed with ${selected.name}.`);toast(`${selected.name} accepts your alliance proposal.`);update()}
function trade(){if(selected.own)return toast('Select another nation to propose a trade deal.');if(wars.has(selected.id))return toast('Trade channels are suspended during conflict.');if(cash<3)return toast('A trade mission costs $3B.');cash-=3;selected.relation=Math.min(100,selected.relation+13);stability=Math.min(90,stability+1);log(`Trade partnership agreed with ${selected.name}.`);toast(`Trade deal signed with ${selected.name} · relations improved.`);update()}
function declare(){if(selected.own)return toast('You cannot declare on your own nation.');if(wars.has(selected.id)){modal('Seek a ceasefire',`<p>Offer an armistice with <b>${selected.name}</b>. Ongoing conflicts drain readiness and weaken both sides each turn.</p>`,'Offer ceasefire',()=>{wars.delete(selected.id);selected.relation=Math.max(10,selected.relation+8);log(`Ceasefire offer accepted by ${selected.name}.`);closeModal();toast('Ceasefire signed. Both sides begin recovery.');update()});return}modal('Declare a game conflict?',`<p>This starts an abstract strategy-game conflict with <b>${selected.flag} ${selected.name}</b>. Prolonged conflict weakens both sides and drains global stability. You can offer a ceasefire at any time.</p><div class="details"><div class="detail"><small>THEIR DEFENSE INDEX</small><strong>${selected.power}/100</strong></div><div class="detail"><small>YOUR TREASURY</small><strong>${fmt(cash)}</strong></div></div>`,'Confirm conflict',()=>{wars.add(selected.id);selected.relation=Math.max(0,selected.relation-25);stability=Math.max(20,stability-4);closeModal();log(`Conflict declared with ${selected.name}; stability drops.`);toast(`Conflict begins with ${selected.name}.`);update()})}
function demand(){if(selected.own)return toast('Select another nation to make a territorial claim.');if(wars.has(selected.id)){toast('Territorial claims are unavailable during conflict. Seek a ceasefire first.');return}modal('Make a territorial claim',`<p>Present a diplomatic claim on a border region to <b>${selected.name}</b>. This is a fictional, abstract game action—not a real territorial assessment.</p><div class="field"><label>CLAIM APPROACH</label><select id="claim"><option>Negotiated transfer · low tension</option><option>International arbitration · balanced</option><option>Hardline demand · high tension</option></select></div><p>Outcome is determined by relations, influence, and a little chance.</p>`,'Present claim',()=>{let mode=$('#claim').value;let chance=selected.relation>65?0.68:selected.relation>40?0.4:0.18;if(mode.includes('low'))chance+=.15;if(mode.includes('high'))chance-=.15;let yes=Math.random()<chance;selected.relation=Math.max(0,selected.relation-(mode.includes('high')?22:8));if(yes){cash+=5;stability=Math.max(20,stability-2);log(`${selected.name} agrees to a symbolic border adjustment.`);toast('Claim accepted · +$5B transition funds.')}else{selected.relation=Math.max(0,selected.relation-8);log(`${selected.name} rejects the territorial claim.`);toast(`${selected.name} rejects the claim; relations worsen.`)}closeModal();update()})}
$('#advance').onclick=endTurn;$('#ally').onclick=pact;$('#demand').onclick=demand;$('#war').onclick=declare;$('#trade').onclick=trade;$('#modal-back').onclick=e=>{if(e.target.id==='modal-back')closeModal()};$('#zoom-in').onclick=()=>{zoom=Math.min(1.3,zoom+.1);drawMap()};$('#zoom-out').onclick=()=>{zoom=Math.max(.9,zoom-.1);drawMap()};$('#fit-btn').onclick=()=>{zoom=1;filter='All nations';$('#filter-btn').textContent='◉  All nations';drawMap()};$('#filter-btn').onclick=()=>{let options=['All nations','Americas','Europe','Asia','Africa','Oceania'];filter=options[(options.indexOf(filter)+1)%options.length];$('#filter-btn').textContent='◉  '+filter;drawMap()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===b.dataset.tab));if(b.dataset.tab==='forces')openForces();if(b.dataset.tab==='design')openDesign();if(b.dataset.tab==='diplomacy')openDiplomacy();if(b.dataset.tab==='overview')toast('World overview selected.')});
drawMap();selectNation(selected);update();
</script></body></html>

