import json, html
W,H=1000,500; data=json.load(open('/tmp/opencode/world.geojson')); parts=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" preserveAspectRatio="none" role="img" aria-label="World map with country boundaries">','<rect width="1000" height="500" fill="#10293a"/>']
def project_ring(ring):
    pts=[]; prev=None
    for lon,lat,*_ in ring:
        if prev is not None:
            while lon-prev>180: lon-=360
            while lon-prev < -180: lon+=360
        prev=lon; pts.append((lon,lat))
    if len(pts)<3:return '',0,0
    d='M '+' L '.join(f'{(lon+180)/360*W:.1f} {(90-lat)/180*H:.1f}' for lon,lat in pts)+' Z'
    xs=[(lon+180)/360*W for lon,lat in pts]
    return d,min(xs),max(xs)
for feature in data['features']:
 p=feature['properties']; name=p.get('ADMIN') or p.get('NAME') or 'Unknown'; geom=feature['geometry']; polys=geom['coordinates'] if geom['type']=='MultiPolygon' else [geom['coordinates']]; pieces=[]; minx=1e9;maxx=-1e9
 for polygon in polys:
  if polygon:
   d,lo,hi=project_ring(polygon[0])
   if d: pieces.append(d);minx=min(minx,lo);maxx=max(maxx,hi)
 if not pieces:continue
 d=' '.join(pieces); safe=html.escape(name,quote=True); offsets=[0]
 if minx<0: offsets.append(1000)
 if maxx>1000: offsets.append(-1000)
 for off in offsets:parts.append(f'<path class="country" data-country="{safe}" d="{d}" transform="translate({off} 0)"><title>{safe}</title></path>')
parts.append('</svg>');open('world-map.svg','w').write('\n'.join(parts));print(len(parts),'elements',sum(map(len,parts)),'bytes')
